# RW4DM_EXPLODE: Explode: a polysurface into its faces, a polyline into its segments. The script rw4dm_explode_script.txt is generated by rw4dm_gen.py. The oracle is exact set / string logic on four objects (ids 1..4 = Point, Line, Plane, Box):
# after each step the objects that List reaches are compared, as id:kind:layer[:name], with the expected list exactly (and the printed message lines with their patterns).
RW4_EXPLODE_OUT=""
if [ -n "${DISPLAY:-}" ] && xset q >/dev/null 2>&1 || ! command -v xvfb-run >/dev/null 2>&1; then
  RW4_EXPLODE_OUT="$(timeout 900 "$BIN" --smoke 60 --script "$HERE/rw4dm_explode_script.txt" 2>&1)" || { echo "$RW4_EXPLODE_OUT" | tail -40; echo "FAIL RW4DM_EXPLODE_run: script exited non-zero"; fail=1; RW4_EXPLODE_OUT=""; }
else
  RW4_EXPLODE_OUT="$(timeout 900 xvfb-run -a -s "-screen 0 1600x900x24" "$BIN" --smoke 60 --script "$HERE/rw4dm_explode_script.txt" 2>&1)" || { echo "$RW4_EXPLODE_OUT" | tail -40; echo "FAIL RW4DM_EXPLODE_run: script exited non-zero"; fail=1; RW4_EXPLODE_OUT=""; }
fi
rw4_explode_block() { awk -v name="$1" '$0 ~ ("Unknown command: RW4BEGIN_" name "$") { on = 1; next } on && /Unknown command: RW4BEGIN_/ { exit } on { print }' <<<"$RW4_EXPLODE_OUT"; }
# rw4_explode_state STEP EXPECTED DESC [PATTERN...]: the objects listed in the step read exactly EXPECTED ("-" = none); each PATTERN must match a printed line of the step
rw4_explode_state() {
  local blk got name desc pat bad want; name="$1"; want="$2"; desc="$3"; blk="$(rw4_explode_block "$name")"
  got="$({ grep -E '^history: Object [0-9]+ \(' <<<"$blk" || true; } | sed -E "s/^history: Object ([0-9]+) \(([^)]*)\) layer (.*) name '(.*)'\$/\1:\2:\3:\4/; s/^history: Object ([0-9]+) \(([^)]*)\) layer (.*)\$/\1:\2:\3/" | tr '\n' ' ' | sed 's/ $//')"; [ -n "$got" ] || got="-"
  bad=""
  shift 3
  for pat in "$@"; do grep -qE "^history: $pat" <<<"$blk" || bad="$bad [$pat]"; done
  if [ "$got" = "$want" ] && [ -z "$bad" ]; then echo "ok   RW4DM_EXPLODE_$name: $desc (objects: $got)"
  else echo "FAIL RW4DM_EXPLODE_$name: $desc (listed '$got', expected '$want'; missing message patterns:${bad:- none})"; fail=1; { grep -E '^history: (Object|!|[A-Za-z]+:)' <<<"$blk" || true; } | head -14 | sed 's/^/     line: /'; fi
}

# rw4_explode_lines STEP REGEX SED EXPECTED DESC SORTFLAG TAG: the lines of the step that match "history: REGEX", with "history: " removed and SED applied, joined by " | " (sorted
# bytewise first when the sixth argument is "sort"), read exactly EXPECTED ("-" = no line)
rw4_explode_lines() {
  local blk got; blk="$(rw4_explode_block "$1")"
  got="$({ grep -E "^history: $2" <<<"$blk" || true; } | sed -E 's/^history: //' | sed -E "$3" | { if [ "${6:-}" = sort ]; then LC_ALL=C sort; else cat; fi; } | paste -sd'|' - | sed 's/|/ | /g')"; [ -n "$got" ] || got="-"
  if [ "$got" = "$4" ]; then echo "ok   RW4DM_EXPLODE_$1_${7:-lines}: $5 (lines: $got)"
  else echo "FAIL RW4DM_EXPLODE_$1_${7:-lines}: $5 (got '$got', expected '$4')"; fail=1; { grep -E '^history: ' <<<"$blk" || true; } | head -14 | sed 's/^/     line: /'; fi
}
rw4_explode_state box "-" "Explode of the 2 x 3 x 4 box makes 6 separate faces" "Exploded into 6 object\(s\)"
rw4_explode_state polyline "-" "Explode of the open polyline (0,0)-(4,0)-(4,3)-(0,3) makes 3 curves of length 4, 3 and 4" "Exploded into 3 object\(s\)"
rw4_explode_state rectangle "-" "Explode of the closed 4 x 3 rectangle polyline makes 4 curves of length 4, 3, 4 and 3" "Exploded into 4 object\(s\)"
rw4_explode_state circle "4:curve:Default" "Explode of a smooth circle (no corner to break at) makes nothing and leaves the circle (4) in place" "Exploded into 0 object\(s\)"
rw4_explode_lines box "Area = " "s/^(Area = [0-9.e+-]+).*/\1/" "Area = 12 | Area = 12 | Area = 6 | Area = 6 | Area = 8 | Area = 8" "the six faces of the 2 x 3 x 4 box have areas 6, 6, 8, 8, 12, 12 (faces 2 x 3, 2 x 4, 3 x 4, twice each)" sort lines
rw4_explode_lines polyline "Curve [0-9]+ length = " "s/^Curve [0-9]+ (length = [0-9.e+-]+)$/\1/" "length = 3 | length = 4 | length = 4" "the three segments are 4, 3 and 4 long (exact to 10 digits)" sort lines
rw4_explode_lines rectangle "Curve [0-9]+ length = " "s/^Curve [0-9]+ (length = [0-9.e+-]+)$/\1/" "length = 3 | length = 3 | length = 4 | length = 4" "the four sides are 4, 3, 4 and 3 long (exact to 10 digits)" sort lines
